public static int maxRegions(int N) {
    if (N == 0) return 1; // Base case: no triangles, one region (the whole plane)
    if (N == 1) return 2; // One triangle divides the plane into 2 regions
    return maxRegions(N - 1) + 4 * (N - 1) + 2;
}

public static int maxRegions(int N) {
    if (N == 0) return 1;
    if (N == 1) return 2;
    int regions = 2;
    for (int i = 1; i <= N; i++) {
        regions += 2 * i;
    }
    return regions;
}

public static int maxRegions(int N) {
    if (N == 0) return 1;
    int regions = 2; // Starting with one triangle
    for (int i = 1; i < N; i++) {
        regions += 4 + 2 * i;
    }
    return regions;
}

public static int maxRegions(int N) {
    if (N == 0) return 1;
    if (N == 1) return 2;
    int regions = 2;
    int additionalRegions = 4;
    for (int i = 1; i < N; i++) {
        regions += additionalRegions;
