    return canTravel(n, start[0], start[1], end[0], end[1], paths, visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravel(int n, int x, int y, int ex, int ey, int[][] paths, boolean[][] visited) {
    if (x < 0 || x >= n || y < 0 || y >= n || visited[x][y]) {
        return false;
    }
    if (x == ex && y == ey) {
        return true;
    }
    visited[x][y] = true;
    for (int[] path : paths) {
        if (path[0] == x && path[1] == y) {
            if (canTravel(n, path[2], path[3], ex, ey, paths, visited)) {
                return true;
            }
        } else if (path[2] == x && path[3] == y) {
            if (canTravel(n, path[0], path[1], ex, ey, paths, visited)) {
                return true;
            }
        }
    }
    return false;
}

public static String appx(String word1, String word2) {
    int commonCount = 0;
    boolean[] used = new boolean[word2.length()];

    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (!used[j] && word1.charAt(i) == word2.charAt(j)) {
                commonCount++;
                used[j] = true;
                break;
            }
        }
    }

    int sumLengths = word1.length() + word2.length();
    int gcd = gcd(commonCount, sumLengths);

    return "appx(" + word1 + ", " + word2 + ") = " + (commonCount / gcd) + "/" + (sumLengths / gcd);
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

