public double trimMean(int[] arr) {
    int n = arr.length;
    int excludeCount = n / 20;
    Arrays.sort(arr);
    double sum = 0;
    for (int i = excludeCount; i < n - excludeCount; i++) {
        sum += arr[i];
    }
    return sum / (n - 2 * excludeCount);
}

