public boolean canArrange(int[] arr, int k) {
    int[] remainderCount = new int[k];
    for (int num : arr) {
        int remainder = ((num % k) + k) % k;
        remainderCount[remainder]++;
    }
    if (remainderCount[0] % 2 != 0) {
        return false;
    }
    for (int i = 1; i <= k / 2; i++) {
        if (remainderCount[i] != remainderCount[k - i]) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    int[] remainderCount = new int[k];
    for (int num : arr) {
        int remainder = num % k;
        if (remainder < 0) {
            remainder += k; // Handle negative numbers
        }
        remainderCount[remainder]++;
    }
    if (remainderCount[0] % 2 != 0) {
        return false; // Numbers with remainder 0 must be even in count
    }
    for (int i = 1; i <= k / 2; i++) {
        if (remainderCount[i] != remainderCount[k - i]) {
            return false; // Counts of remainders i and k-i must be equal
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr.length % 2 != 0) {
        return false;
    }

    int[] remainderCount = new int[k];
    for (int num : arr) {
        int remainder = ((num % k) + k) % k; // Handle negative numbers
        remainderCount[remainder]++;
    }

    for (int i = 1; i <= k / 2; i++) {
        if (remainderCount[i] != remainderCount[k - i]) {
            return false;
        }
    }

    // Check if elements with remainder 0 can be paired among themselves
    if (remainderCount[0] % 2 != 0) {
        return false;
    }

    return true;
}

