public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        graph.get(edge[0]).add(edge[1]);
        graph.get(edge[1]).add(edge[0]);
    }
    return dfs(graph, hasApple, 0, -1);
}

private int dfs(List<List<Integer>> graph, boolean[] hasApple, int node, int parent) {
    int totalTime = 0;
    for (int neighbor : graph.get(node)) {
        if (neighbor == parent) continue;
        int childTime = dfs(graph, hasApple, neighbor, node);
        if (childTime > 0 || hasApple[neighbor]) {
            totalTime += childTime + 2;
        }
    }
    return totalTime;
}

