public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) return false;

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[][][] dp = new boolean[n + 1][n / 2 + 1][sum + 1];
    dp[0][0][0] = true;

    for (int i = 1; i <= n; i++) {
        for (int j = Math.min(i, n / 2); j >= 1; j--) {
            for (int k = 0; k <= sum; k++) {
                if (dp[i - 1][j][k]) {
                    dp[i][j][k] = true;
                    if (k + nums[i - 1] <= sum) {
                        dp[i][j + 1][k + nums[i - 1]] = true;
                    }
                }
            }
        }
    }

    for (int j = 1; j <= n / 2; j++) {
        if (sum * j % n == 0 && dp[n][j][sum * j / n]) {
            return true;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    // dp[i][j] will be true if we can find a subset of first i numbers with sum j
    boolean[][] dp = new boolean[n + 1][sum + 1];
    for (int i = 0; i <= n; i++) {
        dp[i][0] = true;
    }

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= sum; j++) {
            dp[i][j] = dp[i - 1][j];
            if (j >= nums[i - 1]) {
                dp[i][j] = dp[i][j] || dp[i - 1][j - nums[i - 1]];
            }
        }
    }

    // Check for each possible size of subset if we can split the array into two parts with the same average
    for (int i = 1; i < n; i++) {
        if (sum * i % n == 0 && dp[n][sum * i / n]) {
            return true;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    // dp[len][sum] will be true if we can select a subset of length 'len' with sum 'sum'
    boolean[][] dp = new boolean[n / 2 + 1][totalSum + 1];
    dp[0][0] = true;

    for (int num : nums) {
        // Traverse backward to avoid using the same number multiple times
        for (int i = n / 2; i > 0; i--) {
            for (int j = totalSum - num; j >= 0; j--) {
                if (dp[i - 1][j]) {
                    dp[i][j + num] = true;
                }
            }
        }
    }

    for (int len = 1; len <= n / 2; len++) {
        if (totalSum * len % n == 0) {
            int targetSum = totalSum * len / n;
            if (dp[len][targetSum]) {
                return true;
            }
        }
    }

    return false;
}

