    }
    return set.size() == (1 << k);
}

public boolean hasAllCodes(String s, int k) {
    Set<String> set = new HashSet<>();
    int need = 1 << k;
    for (int i = 0; i + k <= s.length() && set.size() < need; i++) {
        set.add(s.substring(i, i + k));
    }
    return set.size() == need;
}

public boolean hasAllCodes(String s, int k) {
    int need = 1 << k;
    boolean[] seen = new boolean[need];
    int allOne = need - 1;
    int hashVal = 0;

    for (int i = 0; i < s.length(); i++) {
        hashVal = ((hashVal << 1) & allOne) | (s.charAt(i) - '0');
        if (i >= k - 1 && !seen[hashVal]) {
            seen[hashVal] = true;
            need--;
        }
        if (need == 0) {
            return true;
        }
    }
    return false;
}

