public int minInsertions(String s) {
    int open = 0;
    int insert = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            open++;
        } else {
            if (open > 0) {
                open--;
            } else {
                insert++;
            }
            if (c == ')' && (s.length() == 1 || s.charAt(s.indexOf(c) + 1) != ')')) {
                insert++;
            } else if (c == ')' && (s.length() > 1 && s.charAt(s.indexOf(c) + 1) == ')')) {
                c = s.charAt(s.indexOf(c) + 1);
            }
        }
    }
    return insert + open * 2;
}

