public int findMinFibonacciNumbers(int k) {
    int a = 1, b = 1;
    while (b <= k) {
        int temp = b;
        b = a + b;
        a = temp;
    }
    int count = 0;
    while (k > 0) {
        k -= a;
        count++;
        int temp = b - a;
        b = a;
        a = temp;
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) return 0;
    int a = 1, b = 1;
    while (b <= k) {
        int temp = a;
        a = b;
        b = temp + b;
    }
    return 1 + findMinFibonacciNumbers(k - a);
}

