public int maxUniqueSplit(String s) {
    return maxUniqueSplitHelper(s, 0, new HashSet<>());
}

private int maxUniqueSplitHelper(String s, int start, Set<String> seen) {
    if (start == s.length()) {
        return 0;
    }
    int maxUnique = 0;
    for (int end = start + 1; end <= s.length(); end++) {
        String substring = s.substring(start, end);
        if (!seen.contains(substring)) {
            seen.add(substring);
            maxUnique = Math.max(maxUnique, 1 + maxUniqueSplitHelper(s, end, seen));
            seen.remove(substring);
        }
    }
    return maxUnique;
}

