public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < n; i++) {
        result.append('a');
    }
    k -= n;
    for (int i = n - 1; i >= 0 && k > 0; i--) {
        int add = Math.min(k, 25);
        result.setCharAt(i, (char) ('a' + add));
        k -= add;
    }
    return result.toString();
}

public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
        k -= 1;
    }
    for (int i = n - 1; i >= 0; i--) {
        int val = Math.min(k, 25);
        result[i] += val;
        k -= val;
    }
    return new String(result);
}

public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    int currentSum = 0;
    for (int i = 0; i < n; i++) {
        int minCharValue = 1;
        if (i == n - 1) {
            minCharValue = k - currentSum;
        } else {
            while (minCharValue + (26 * (n - i - 1)) < k) {
                minCharValue++;
            }
        }
        result.append((char) (minCharValue + 'a' - 1));
        currentSum += minCharValue;
    }
    return result.toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    int remainingValue = k - n;
    for (int i = 0; i < n; i++) {
        if (remainingValue > 25) {
            result.append('a');
            remainingValue -= 1;
        } else {
            char c = (char) ('a' + remainingValue);
            result.append(c);
            remainingValue = 0;
        }
    }
    return result.reverse().toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    int remainingValue = k - n; // Since each character at least contributes 1 to the sum
    for (int i = 0; i < n; i++) {
        if (remainingValue >= 25) {
            result.append('z');
            remainingValue -= 25;
        } else {
            result.append((char) ('a' + remainingValue));
            remainingValue = 0;
        }
    }
    return result.toString();
}

