private static void dfs(List<Integer> result, int current, int low, int high) {
    if (current > high) return;
    for (int i = -1; i <= 1; i += 2) {
        int lastDigit = current % 10;
        int nextDigit = lastDigit + i;
        if (nextDigit >= 0 && nextDigit <= 9) {
            int nextNumber = current * 10 + nextDigit;
            if (nextNumber >= low) result.add(nextNumber);
            dfs(result, nextNumber, low, high);
        }
    }
}

