public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;

    // Horizontal, Vertical, Diagonal, Anti-diagonal
    int[][][] dp = new int[m][n][4];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                // Horizontal
                dp[i][j][0] = (j > 0) ? dp[i][j - 1][0] + 1 : 1;
                // Vertical
                dp[i][j][1] = (i > 0) ? dp[i - 1][j][1] + 1 : 1;
                // Diagonal
                dp[i][j][2] = (i > 0 && j > 0) ? dp[i - 1][j - 1][2] + 1 : 1;
                // Anti-diagonal
                dp[i][j][3] = (i > 0 && j < n - 1) ? dp[i - 1][j + 1][3] + 1 : 1;

                // Update the maxLength
                for (int k = 0; k < 4; k++) {
                    maxLength = Math.max(maxLength, dp[i][j][k]);
                }
            }
        }
    }

    return maxLength;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) return 0;
    int m = mat.length, n = mat[0].length;
    int maxCount = 0;

    // Check horizontally
    for (int i = 0; i < m; i++) {
        int count = 0;
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                count++;
                maxCount = Math.max(maxCount, count);
            } else {
                count = 0;
            }
        }
    }

    // Check vertically
    for (int j = 0; j < n; j++) {
        int count = 0;
        for (int i = 0; i < m; i++) {
            if (mat[i][j] == 1) {
                count++;
                maxCount = Math.max(maxCount, count);
            } else {
                count = 0;
            }
        }
    }

    // Check diagonally
    for (int k = -m + 1; k < n; k++) {
        int count = 0;
        for (int j = Math.max(0, k); j < Math.min(m, n + k); j++) {
            if (mat[j][j - k] == 1) {
                count++;
                maxCount = Math.max(maxCount, count);
            } else {
                count = 0;
            }
        }
    }

    // Check anti-diagonally
    for (int k = 0; k < m + n - 1; k++) {
        int count = 0;
        for (int j = Math.max(0, k - m + 1); j < Math.min(n, k + 1); j++) {
            if (mat[k - j][j] == 1) {
                count++;
                maxCount = Math.max(maxCount, count);
            } else {
                count = 0;
            }
        }
    }

    return maxCount;
}

