public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;

    // Horizontal
    for (int i = 0; i < m; i++) {
        int count = 0;
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                count++;
                maxLength = Math.max(maxLength, count);
            } else {
                count = 0;
            }
        }
    }

    // Vertical
    for (int j = 0; j < n; j++) {
        int count = 0;
        for (int i = 0; i < m; i++) {
            if (mat[i][j] == 1) {
                count++;
                maxLength = Math.max(maxLength, count);
            } else {
                count = 0;
            }
        }
    }

    // Diagonal
    for (int k = -m + 1; k < n; k++) {
        int count = 0;
        for (int j = Math.max(k, 0); j < n && j - k < m; j++) {
            if (mat[j - k][j] == 1) {
                count++;
                maxLength = Math.max(maxLength, count);
            } else {
                count = 0;
            }
        }
    }

    // Anti-diagonal
    for (int k = 0; k < m + n - 1; k++) {
        int count = 0;
        for (int j = Math.min(k, n - 1); j >= 0 && k - j < m; j--) {
            if (mat[k - j][j] == 1) {
                count++;
                maxLength = Math.max(maxLength, count);
            } else {
                count = 0;
            }
        }
    }

    return maxLength;
}

