private static int backtrack(int[] A, boolean[] used, List<Integer> currentPermutation) {
    if (currentPermutation.size() == A.length) {
        return 1;
    }

    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if (!used[i]) {
            if (currentPermutation.isEmpty() || isPerfectSquare(currentPermutation.get(currentPermutation.size() - 1) + A[i])) {
                used[i] = true;
                currentPermutation.add(A[i]);
                count += backtrack(A, used, currentPermutation);
                currentPermutation.remove(currentPermutation.size() - 1);
                used[i] = false;

                // Skip duplicates
                while (i < A.length - 1 && A[i] == A[i + 1]) {
                    i++;
