    }

    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, heights[i] * (right[i] - left[i] - 1));
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) return new int[0];
    int m = mat.length, n = mat[0].length;
    int[] result = new int[m * n];
    int r = 0, c = 0, d = 0;
    int[][] dirs = {{-1, 1}, {1, -1}};
    for (int i = 0; i < m * n; i++) {
        result[i] = mat[r][c];
        r += dirs[d][0];
        c += dirs[d][1];
        if (r >= m) { r = m - 1; c += 2; d = 1 - d; }
        if (c >= n) { c = n - 1; r += 2; d = 1 - d; }
        if (r < 0) { r = 0; d = 1 - d; }
        if (c < 0) { c = 0; d = 1 - d; }
    }
    return result;
}

