        result.add("8");
        n--;
    }
    centerSymmetricNumbersHelper(n, result, "");
    return result;
}

private static void centerSymmetricNumbersHelper(int length, List<String> result, String current) {
    if (length == 0) {
        result.add(current);
        return;
    }
    if (length != 2 || current.length() > 0) {
        centerSymmetricNumbersHelper(length - 2, result, "0" + current + "0");
    }
    centerSymmetricNumbersHelper(length - 2, result, "1" + current + "1");
    centerSymmetricNumbersHelper(length - 2, result, "6" + current + "9");
    centerSymmetricNumbersHelper(length - 2, result, "8" + current + "8");
    centerSymmetricNumbersHelper(length - 2, result, "9" + current + "6");
}

