private static List<String> helper(int currentLen, int targetLen) {
    if (currentLen == 0) return new ArrayList<>(Arrays.asList(""));
    if (currentLen == 1) return new ArrayList<>(Arrays.asList("0", "1", "8"));

    List<String> subResult = helper(currentLen - 2, targetLen);
    List<String> result = new ArrayList<>();

    for (String mid : subResult) {
        if (currentLen != targetLen) result.add("0" + mid + "0");
        result.add("1" + mid + "1");
        result.add("6" + mid + "9");
        result.add("8" + mid + "8");
        result.add("9" + mid + "6");
    }

    return result;
}

